      "tipo": "GPU",
      "causa_raiz": "Tempo de GPU atingindo 28.27ms (limite de 16.67ms para 60 FPS), com 69 violações registradas. A carga de rasterização e pós-processamento excede a taxa de preenchimento (fillrate) da GTX 1650 na resolução nativa.",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class DynamicResolutionAndQualityController : MonoBehaviour
{
    [Header("Dynamic Resolution")]
    [Range(0.5f, 1.0f)] public float minRenderScale = 0.65f;
    [Range(0.5f, 1.0f)] public float maxRenderScale = 1.0f;
    public float targetFrameTimeMs = 16.0f;
    private float currentScale = 1.0f;

    [Header("GPU Throttling Safety")]
    public int targetFrameRate = 60;

    void Awake()
    {
        Application.targetFrameRate = targetFrameRate;
        QualitySettings.vSyncCount = 0;
    }

    void Update()
    {
        float currentFrameTimeMs = Time.unscaledDeltaTime * 1000f;
        if (currentFrameTimeMs > targetFrameTimeMs)
        {
            currentScale = Mathf.Max(minRenderScale, currentScale - 0.05f);
        }
        else if (currentFrameTimeMs < targetFrameTimeMs - 2.0f)
        {
            currentScale = Mathf.Min(maxRenderScale, currentScale + 0.02f);
        }

        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) está demorando quase o dobro do tempo permitido para desenhar os pixels na tela (28.27ms em vez de 16.7ms). Esse script ajusta dinamicamente a resolução interna do jogo quando o hardware sofre lentidão, aliviando a carga sobre a GTX 1650 instantaneamente sem travar a interface do usuário."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Alocação de cerca de 96 KB no frame gerando pausa de 5.60ms por Garbage Collection (GC.Collect), roubando tempo precioso da CPU.",
      "codigo_refatorado": "using UnityEngine;

public class NonAllocBufferManager : MonoBehaviour
{
    private static readonly RaycastHit[] s_HitBuffer = new RaycastHit[32];
    private static readonly Collider[] s_OverlapBuffer = new Collider[32];

    public static int PerformRaycastNonAlloc(Ray ray, float distance, int layerMask)
    {
        return Physics.RaycastNonAlloc(ray, s_HitBuffer, distance, layerMask);
    }

    public static int PerformOverlapSphereNonAlloc(Vector3 position, float radius, int layerMask)
    {
        return Physics.OverlapSphereNonAlloc(position, radius, s_OverlapBuffer, layerMask);
    }
}",
      "explicacao_didatica": "Quando o código cria arrays ou variáveis temporárias dentro de funções que rodam a cada frame (como Physics.RaycastAll), a Unity precisa acionar o lixeiro automático (Garbage Collector). Isso congelou o jogo por 5.6ms. O código corrigido reutiliza uma lista pré-alocada (NonAlloc), evitando a geração de lixo."
    }
  ],
  "dicas_level_design": null
}

